 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find solid monochrome 3x3 objects, and project their center row/column.
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))
    projected = {}
    for cr, cc, color in blocks:
        for x in range(w):
            projected.setdefault((cr, x), set()).add(color)
        for y in range(h):
            projected.setdefault((y, cc), set()).add(color)
    for (r, c), colors in projected.items():
        if len(colors) > 1:
            # Different colored beams cancel at their intersection.
            out[r][c] = 0
        elif grid[r][c] == 0:
            out[r][c] = next(iter(colors))
    return out
